/* Maithili Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Ram": "pleasing, charming — Sanskrit", "Sita": "furrow — Sanskrit", "Mohan": "enchanter — Sanskrit", "Janki": "daughter of Janaka — Sanskrit", "Gita": "song — Sanskrit", "Madhav": "descendant of Madhu — Sanskrit, epithet of Krishna", "Jha": "The signature Maithil Brahmin surname.", "Mishra": "A widespread Maithil surname.", "Thakur": "A respected surname.", "Choudhary": "A widespread community surname."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Ram';
console.log(lookup(q));

